#include <stdlib.h>

int compare(const void *a, const void *b) {
    int *x = (int *)a;
    int *y = (int *)b;

    if (x[0] == y[0]) return x[1] - y[1];
    return x[0] - y[0];
}

int main() {
    int n;
    scanf("%d", &n);

    int arr[n];
    for(int i = 0; i < n; i++) {
        scanf("%d", &arr[i]);
    }

    int target;
    scanf("%d", &target);

    int pairs[n][2];
    int count = 0;

    for(int i = 0; i < n; i++) {
        for(int j = i + 1; j < n; j++) {
            if(arr[i] + arr[j] == target) {
                int a = arr[i] < arr[j] ? arr[i] : arr[j];
                int b = arr[i] > arr[j] ? arr[i] : arr[j];
                pairs[count][0] = a;
                pairs[count][1] = b;
                count++;
            }
        }
    }

    qsort(pairs, count, sizeof(pairs[0]), compare);

    for(int i = 0; i < count; i++) {
        if(i == 0 || pairs[i][0] != pairs[i-1][0] || pairs[i][1] != pairs[i-1][1]) {
            printf("%d %d\n", pairs[i][0], pairs[i][1]);
        }
    }

    return 0;
}

import java.util.*;
class Pair{int val,idx; Pair(int v,int i){val=v;idx=i;}}
public class Solution{
 public static void main(String[] args){
  Scanner sc=new Scanner(System.in);
  int n=sc.nextInt();
  Pair[] arr=new Pair[n];
  for(int i=0;i<n;i++) arr[i]=new Pair(sc.nextInt(),i);
  Arrays.sort(arr,(a,b)->a.val-b.val);
  boolean[] vis=new boolean[n];
  int ans=0;
  for(int i=0;i<n;i++){
   if(vis[i]||arr[i].idx==i) continue;
   int cycle=0,j=i;
   while(!vis[j]){
    vis[j]=true;
    j=arr[j].idx;
    cycle++;
   }
   ans+=cycle-1;
  }
  System.out.println(ans);
 }
}

