#include <stdio.h>

int main() {
    int n;

    scanf("%d", &n);

    int a[n];
    for (int i = 0; i < n; i++) {
        scanf("%d", &a[i]);
    }

    // Find the first index 'i' from the end where a[i] < a[i+1]
    int i = n - 2;
    while (i >= 0 && a[i] >= a[i + 1]) {
        i--;
    }

    if (i >= 0) {
        // Find the first element from the end that is greater than a[i]
        int j = n - 1;
        while (a[j] <= a[i]) {
            j--;
        }

        // Swap a[i] and a[j]
        int t = a[i];
        a[i] = a[j];
        a[j] = t;
    }

    // Reverse the subarray from i+1 to n-1
    int l = i + 1, r = n - 1;
    while (l < r) {
        int t = a[l];
        a[l] = a[r];
        a[r] = t;
        l++;
        r--;
    }

    // Print the next permutation
    for (int k = 0; k < n; k++) {
        printf("%d ", a[k]);
    }

    return 0;
}

