        p[i + 1] = p[i] + a[i];
    }

    qsort(p, n + 1, sizeof(long long), cmp);

    long long best = LLONG_MAX;


    for (int i = 1; i <= n; i++) {
        long long d = llabs(p[i] - p[i - 1]);
        if (d < best) best = d;
    }

    printf("%lld", best);

