 int l=0,res=0;
 for(int r=0;r<a.size();r++){
  mp[a[r]]++;
  while(mp.size()>k){
   mp[a[l]]--;
   if(mp[a[l]]==0) mp.erase(a[l]);
   l++;
  }
  res+=r-l+1;
 }
