int atMost(int *a, int n, int k) {
    int freq[10001] = {0}, l = 0, res = 0, distinct = 0;
    for (int r = 0; r < n; r++) {
        if (freq[a[r]]++ == 0) distinct++;
        while (distinct > k) {
            if (--freq[a[l++]] == 0) distinct--;
        }
        res += r - l + 1;
    }
    return res;
}

