  Scanner sc=new Scanner(System.in);
  String s=sc.nextLine();
  String t=sc.nextLine();
  Map<Character,Integer> need=new HashMap<>();
  for(char c:t.toCharArray()) need.put(c,need.getOrDefault(c,0)+1);
  Map<Character,Integer> have=new HashMap<>();
  int req=need.size(),formed=0,l=0;
  int minLen=Integer.MAX_VALUE,start=0;
  for(int r=0;r<s.length();r++){
   char c=s.charAt(r);
   have.put(c,have.getOrDefault(c,0)+1);
   if(need.containsKey(c)&&have.get(c).intValue()==need.get(c).intValue()) formed++;
   while(l<=r&&formed==req){
    if(r-l+1<minLen){minLen=r-l+1;start=l;}
    char ch=s.charAt(l);
    have.put(ch,have.get(ch)-1);
    if(need.containsKey(ch)&&have.get(ch)<need.get(ch)) formed--;
    l++;
   }
  }
  System.out.println(minLen==Integer.MAX_VALUE?-1:s.substring(start,start+minLen));
 }
}

