#include <stdio.h>
#define MAX(a,b,c) ((a)>(b)?((a)>(c)?(a):(c)):((b)>(c)?(b):(c)))
#define MIN(a,b,c) ((a)<(b)?((a)<(c)?(a):(c)):((b)<(c)?(b):(c)))
int main() {
    int n; scanf("%d",&n);
    int a[20005]; for(int i=0;i<n;i++) scanf("%d",&a[i]);
    int mx=a[0],mn=a[0],res=a[0];
    for(int i=1;i<n;i++){
        int tmp=mx;
        mx=MAX(a[i],tmp*a[i],mn*a[i]);
        mn=MIN(a[i],tmp*a[i],mn*a[i]);
        if(mx>res) res=mx;
    }
    printf("%d\n",res); return 0;
}
